  "language": "java",
  "question": "Sum of First N Natural Numbers: Given a positive integer n, return the sum of all natural numbers from 1 to n.",
  "code": "public static void mergeSort(int[] nums, int l, int r) {
    if (l >= r) return;
    int m = (l + r) / 2;
    mergeSort(nums, l, m);
    mergeSort(nums, m + 1, r);
    int[] tmp = new int[r - l + 1];
    int p = l, q = m + 1, t = 0;
    while (p <= m && q <= r) tmp[t++] = nums[p] <= nums[q] ? nums[p++] : nums[q++];
    while (p <= m) tmp[t++] = nums[p++];
    while (q <= r) tmp[t++] = nums[q++];
    for (int w = 0; w < tmp.length; w++) nums[l + w] = tmp[w];
}"
}

